UPDATE PERMISSIONS
   SET
       NAME               = COALESCE(#{name}, NAME)
     , REMARK             = COALESCE(#{description}, REMARK)
     , STATUS             = COALESCE(#{status}, STATUS)
     , OWNER_ROLE_ID      = COALESCE(#{roleId}, OWNER_ROLE_ID)
     , SYSTEM             = COALESCE(#{system}, SYSTEM)
     , MENU_ID            = COALESCE(#{menuId}, MENU_ID)
     , MENU_NAME          = COALESCE(#{menuName}, MENU_NAME)
     , LAST_CHANGE_BRANCH = #{lastChangeBranch}
     , LAST_CHANGE_USER   = #{lastChangeUser}
     , LAST_CHANGE_DATE   = #{lastChangeDate}
     , LAST_CHANGE_TIME   = #{lastChangeTime}
 WHERE PERMISSION_ID      = #{permissionId}


UPDATE PERMISSIONS
   SET
       STATUS             = '09'
     , LAST_CHANGE_USER   = #{lastChangeUser}
     , LAST_CHANGE_DATE   = #{lastChangeDate}
     , LAST_CHANGE_TIME   = #{lastChangeTime}
 WHERE PERMISSION_ID = #{permissionId}
